11	import XCTest
12	
13	/// The harnesses' plain-HTTP control ports, over loopback.
14	///
15	/// One implementation, because there were three: each suite had its own private
16	/// `get`/`post` pair, `get` checked the status code in all three and `post`
17	/// checked it in none. A `POST /__mode?front=502` aimed at the wrong server
18	/// therefore returned 404, threw nothing, and the test that depended on it
19	/// asserted against a perfectly healthy dashboard — then hung for two minutes
20	/// waiting for an error page that was never going to appear. A control call
21	/// that does nothing must fail the test that made it.
22	enum HarnessControl {
23	    /// Thrown for any non-2xx. Carries the URL because the usual cause is a
24	    /// path or a port that does not exist on the server being asked.
25	    struct BadStatus: Error, CustomStringConvertible {
26	        let method: String
27	        let url: String
28	        let status: Int
29	        let body: String
30	        var description: String {
31	            "\(method) \(url) answered \(status), not 2xx"
32	                + (body.isEmpty ? "" : ": \(body.prefix(200))")
33	        }
34	    }
35	
36	    static func get(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
37	        try await send("GET", url, timeout: timeout)
38	    }
39	
40	    @discardableResult
41	    static func post(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
42	        try await send("POST", url, timeout: timeout)
43	    }
44	
45	    private static func send(_ method: String, _ url: String,
46	                             timeout: TimeInterval) async throws -> Data {
47	        var request = URLRequest(url: URL(string: url)!, timeoutInterval: timeout)
48	        request.httpMethod = method
49	        let (data, response) = try await URLSession.shared.data(for: request)
50	        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
51	        guard (200...299).contains(status) else {
52	            throw BadStatus(method: method, url: url, status: status,
53	                            body: String(decoding: data, as: UTF8.self))
54	        }
55	        return data
56	    }
57	}
58	
59	/// Which harness instance a run talks to, and on which ports (F14).
60	///
61	/// Two suite runs at once need two harnesses, so the ports are not constants:
62	/// the suite scripts read an instance's ports from `make ports` and hand them
63	/// to xcodebuild as `TEST_RUNNER_LATCHKEY_<NAME>`, which reach this process as
64	/// `LATCHKEY_<NAME>`. Absent, each is the Makefiles' default (instance 0),
65	/// which is what a single run has always used.
66	enum HarnessInstance {
67	    static let id = ProcessInfo.processInfo.environment["LATCHKEY_HARNESS_INSTANCE"] ?? "0"
68	
69	    static func port(_ name: String, default fallback: Int) -> Int {
70	        guard let raw = ProcessInfo.processInfo.environment["LATCHKEY_\(name)"] else { return fallback }
71	        guard let port = Int(raw), (1...65535).contains(port) else {
72	            preconditionFailure("LATCHKEY_\(name)=\(raw) is not a port")
73	        }
74	        return port
75	    }
76	
77	    /// Fails unless the server behind `stateURL` (a control endpoint whose
78	    /// JSON carries `instance`) is this run's instance. Ports are the only
79	    /// thing keeping two instances apart, and a run that reached its sibling
80	    /// would change modes under the sibling's tests and pass on its journal.
81	    static func assertIsOurs(_ stateURL: String) async throws {
82	        let state = try JSONSerialization.jsonObject(
83	            with: try await HarnessControl.get(stateURL)) as? [String: Any]
84	        let theirs = state?["instance"] as? String ?? "<none>"
85	        guard theirs == id else { throw WrongInstance(url: stateURL, theirs: theirs, ours: id) }
86	    }
87	
88	    struct WrongInstance: Error, CustomStringConvertible {
89	        let url: String, theirs: String, ours: String
90	        var description: String { "\(url) is harness instance \(theirs), not this run's \(ours)" }
91	    }
92	}
93	
94	extension XCUIElement {
95	    /// `waitForExistence`, polled every 100 ms. XCTest's own wait first looks
96	    /// about a second after it starts and then once a second (F14 §4.1,
97	    /// measured: 1.07 s for an element already on screen), so every wait for
98	    /// something that is there cost a second, dozens of times per suite. Same
99	    /// answer, same timeout; only the polling is finer.
100	    @MainActor
101	    func appears(within timeout: TimeInterval) -> Bool {
102	        let deadline = Date().addingTimeInterval(timeout)
103	        while !exists {
104	            if Date() >= deadline { return false }
105	            Thread.sleep(forTimeInterval: 0.1)
106	        }
107	        return true
108	    }
109	
110	    /// `waitForNonExistence`, polled the same way.
111	    @MainActor
112	    func disappears(within timeout: TimeInterval) -> Bool {
113	        let deadline = Date().addingTimeInterval(timeout)
114	        while exists {
115	            if Date() >= deadline { return false }
116	            Thread.sleep(forTimeInterval: 0.1)
117	        }
118	        return true
119	    }
120	
121	    /// Taps this element once it exists, the app has no presentation or
122	    /// dismissal in progress, and it is hittable; fails the test otherwise.
123	    ///
124	    /// `tap()` alone is not enough, twice over. An element is in the tree from
125	    /// the first frame of the sheet it is on, while UIKit still drops touches,
126	    /// so a tap straight after `appears` can reach nothing. And a tap on an
127	    /// element that is covered (a sheet still over it) synthesizes a touch at
128	    /// {-1, -1} and reports no error, so the failure shows up steps later.
129	    @MainActor
130	    func tapWhenSettled(in app: XCUIApplication, timeout: TimeInterval = 10,
131	                        file: StaticString = #filePath, line: UInt = #line) {
132	        guard appears(within: timeout) else {
133	            XCTFail("\(self) never appeared", file: file, line: line)
134	            return
135	        }
136	        guard app.settles(within: timeout) else {
137	            XCTFail("a presentation was still moving after \(timeout) s; not tapping \(self)", file: file, line: line)
138	            return
139	        }
140	        let deadline = Date().addingTimeInterval(2)
141	        while !isHittable {
142	            if Date() >= deadline {
143	                XCTFail("\(self) is not hittable once settled (covered?)", file: file, line: line)
144	                return
145	            }
146	            Thread.sleep(forTimeInterval: 0.1)
147	        }
148	        tap()
149	    }
150	
151	    /// Scrolls `container` until this element is on screen. Settings opens as
152	    /// a half sheet, and Forms and Lists build their rows lazily: a row below
153	    /// the fold is not in the tree until it is scrolled to. Slow swipes, and
154	    /// back down if one carried the row past the top.
155	    ///
156	    /// A row below the fold does not appear by waiting, only by swiping, so
157	    /// each step waits half a second rather than the two it used to: that wait
158	    /// was paid in full before every swipe (F14: ~8 s of Status's commit row).
159	    @MainActor
160	    func reveal(scrolling container: XCUIElement, swipes: Int = 8) -> Bool {
161	        for _ in 0..<swipes {
162	            if appears(within: 0.5), isHittable { return true }
163	            if exists, frame.maxY < container.frame.midY {
164	                container.swipeDown(velocity: .slow)
165	            } else {
166	                container.swipeUp(velocity: .slow)
167	            }
168	        }
169	        return appears(within: 2) && isHittable
170	    }
171	}
172	
173	extension XCUIApplication {
174	    /// Whether no view controller is being presented or dismissed (the app's
175	    /// `ui-presentation` probe, Testing builds), polled every 100 ms. Pair it
176	    /// with an element's `appears`: the element proves the sheet began,
177	    /// `settled` that it finished.
178	    @MainActor
179	    func settles(within timeout: TimeInterval) -> Bool {
180	        let probe = otherElements["ui-presentation"].firstMatch
181	        let deadline = Date().addingTimeInterval(timeout)
182	        while !(probe.exists && probe.value as? String == "settled") {
183	            if Date() >= deadline { return false }
184	            Thread.sleep(forTimeInterval: 0.1)
185	        }
186	        return true
187	    }
188	
189	    /// Settings → Status, from the dashboard's gear.
190	    @MainActor
191	    func openStatus(file: StaticString = #filePath, line: UInt = #line) -> XCUIElement {
192	        // Callers often come here straight from closing a sheet, which may
193	        // still be sliding over the gear.
194	        buttons["settings-button"].firstMatch.tapWhenSettled(in: self, file: file, line: line)
195	        XCTAssertTrue(navigationBars["Settings"].appears(within: 10), "the gear opens Settings",
196	                      file: file, line: line)
197	        let status = buttons["status-button"]
198	        XCTAssertTrue(status.reveal(scrolling: collectionViews.firstMatch), "Settings has a Status entry",
199	                      file: file, line: line)
200	        // `reveal` settles for hittable, which the row already is mid-slide.
201	        status.tapWhenSettled(in: self, file: file, line: line)
202	        let list = collectionViews["diagnostics-list"]
203	        XCTAssertTrue(list.appears(within: 10), "Status opens", file: file, line: line)
204	        return list
205	    }
206	
207	    /// The value of a Status row (`diag-<label>`), scrolled to and settled
208	    /// (the cookie rows read "reading…", availability "checking", until they
209	    /// know); a `<missing …>` marker when there is no such row.
210	    @MainActor
211	    func statusRow(_ id: String, in list: XCUIElement) -> String {
212	        let e = list.descendants(matching: .any).matching(identifier: id).firstMatch
213	        guard e.reveal(scrolling: list) else { return "<missing \(id)>" }
214	        // Polled rather than an XCTNSPredicateExpectation, which first looks
215	        // after a second even when the row has long settled.
216	        let deadline = Date().addingTimeInterval(10)
217	        var label = e.label
218	        while label.contains("reading…") || label.hasSuffix("checking"), Date() < deadline {
219	            Thread.sleep(forTimeInterval: 0.1)
220	            label = e.label
221	        }
222	        return label
223	    }
224	}
